-- 0062: het blok Bronnen onder elke gids (november 2026, docs/adr/0005-auteurs-bronnen-gidseneditor.md).
--
-- De gidsen van 0060 staan in de database zonder het blok gidsBronnen, en de SQL van 0061
-- is gegenereerd vóór dat blok bestond. Dit zet onder elke gids het bronnenblok uit
-- src/content/<slug>.json, direct vóór het blok "Zo helpt React2u" (gidsHelpt); de blokken
-- daarna schuiven één plaats op. Een gids die het blok al heeft (bijvoorbeeld via het beheer)
-- wordt overgeslagen, net als een pagina die (nog) niet bestaat: de migratie kan vóór of ná
-- 0061 draaien en meer dan eens.
--
-- Gidsen: arbeidsdeskundig-onderzoek, arbodienst, bedrijfsarts, casemanager-verzuim, eigenrisicodrager-ziektewet, loonsanctie, preventiemedewerker, re-integratie, rie, twee-jaar-ziek, verzuimverzekering, wet-verbetering-poortwachter, zieke-werknemer
--
-- Draaien: supabase db query --linked -f supabase/migrations/0062_gidsen_bronnen.sql
-- In de code verandert niets: de concepten bevatten het blok al, en MIGRATIE_RESERVE blijft zoals na 0061.

begin;

do $$
declare
  r record;
  pid uuid;
  plek int;
begin
  for r in
    select * from jsonb_to_recordset($bronnen$[{"slug": "arbeidsdeskundig-onderzoek", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "arbodienst", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Arbeidsomstandighedenwet (Arbowet)", "href": "https://wetten.overheid.nl/BWBR0010346", "uitgever": "wetten.overheid.nl"}, {"titel": "Arboportaal: Arbowet, RI&E, preventiemedewerker en basiscontract", "href": "https://www.arboportaal.nl/", "uitgever": "Ministerie van Sociale Zaken en Werkgelegenheid"}, {"titel": "SBCA: de certificatieregeling voor arbodiensten", "href": "https://www.sbca.nl/", "uitgever": "Stichting Beheer Certificatie Arbodiensten"}, {"titel": "Nederlandse Arbeidsinspectie: toezicht op de Arbowet", "href": "https://www.nlarbeidsinspectie.nl/", "uitgever": "Nederlandse Arbeidsinspectie"}]}}, {"slug": "bedrijfsarts", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Arbeidsomstandighedenwet (Arbowet)", "href": "https://wetten.overheid.nl/BWBR0010346", "uitgever": "wetten.overheid.nl"}, {"titel": "Arbeidsomstandighedenbesluit", "href": "https://wetten.overheid.nl/BWBR0008498", "uitgever": "wetten.overheid.nl"}, {"titel": "Arboportaal: Arbowet, RI&E, preventiemedewerker en basiscontract", "href": "https://www.arboportaal.nl/", "uitgever": "Ministerie van Sociale Zaken en Werkgelegenheid"}, {"titel": "Autoriteit Persoonsgegevens: wat een werkgever mag vastleggen bij ziekte", "href": "https://www.autoriteitpersoonsgegevens.nl/", "uitgever": "Autoriteit Persoonsgegevens"}]}}, {"slug": "casemanager-verzuim", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Autoriteit Persoonsgegevens: wat een werkgever mag vastleggen bij ziekte", "href": "https://www.autoriteitpersoonsgegevens.nl/", "uitgever": "Autoriteit Persoonsgegevens"}]}}, {"slug": "eigenrisicodrager-ziektewet", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Ziektewet", "href": "https://wetten.overheid.nl/BWBR0001888", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Ziektewet en eigenrisicodragerschap", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Belastingdienst: eigenrisicodragerschap en de gedifferentieerde premie Whk", "href": "https://www.belastingdienst.nl/", "uitgever": "Belastingdienst"}]}}, {"slug": "loonsanctie", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "Wet werk en inkomen naar arbeidsvermogen (WIA)", "href": "https://wetten.overheid.nl/BWBR0019057", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "preventiemedewerker", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Arbeidsomstandighedenwet (Arbowet)", "href": "https://wetten.overheid.nl/BWBR0010346", "uitgever": "wetten.overheid.nl"}, {"titel": "Arboportaal: Arbowet, RI&E, preventiemedewerker en basiscontract", "href": "https://www.arboportaal.nl/", "uitgever": "Ministerie van Sociale Zaken en Werkgelegenheid"}, {"titel": "Nederlandse Arbeidsinspectie: toezicht op de Arbowet", "href": "https://www.nlarbeidsinspectie.nl/", "uitgever": "Nederlandse Arbeidsinspectie"}]}}, {"slug": "re-integratie", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "Burgerlijk Wetboek Boek 7, titel 10 (arbeidsovereenkomst, loondoorbetaling bij ziekte)", "href": "https://wetten.overheid.nl/BWBR0005290", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "rie", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Arbeidsomstandighedenwet (Arbowet)", "href": "https://wetten.overheid.nl/BWBR0010346", "uitgever": "wetten.overheid.nl"}, {"titel": "Arbeidsomstandighedenbesluit", "href": "https://wetten.overheid.nl/BWBR0008498", "uitgever": "wetten.overheid.nl"}, {"titel": "Steunpunt RI&E: erkende branche-instrumenten en de toetsing", "href": "https://www.rie.nl/", "uitgever": "Steunpunt RI&E"}, {"titel": "Nederlandse Arbeidsinspectie: toezicht op de Arbowet", "href": "https://www.nlarbeidsinspectie.nl/", "uitgever": "Nederlandse Arbeidsinspectie"}]}}, {"slug": "twee-jaar-ziek", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet werk en inkomen naar arbeidsvermogen (WIA)", "href": "https://wetten.overheid.nl/BWBR0019057", "uitgever": "wetten.overheid.nl"}, {"titel": "Burgerlijk Wetboek Boek 7, titel 10 (arbeidsovereenkomst, loondoorbetaling bij ziekte)", "href": "https://wetten.overheid.nl/BWBR0005290", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "verzuimverzekering", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Burgerlijk Wetboek Boek 7, titel 10 (arbeidsovereenkomst, loondoorbetaling bij ziekte)", "href": "https://wetten.overheid.nl/BWBR0005290", "uitgever": "wetten.overheid.nl"}, {"titel": "Verbond van Verzekeraars: de mkb verzuim-ontzorgverzekering", "href": "https://www.verzekeraars.nl/", "uitgever": "Verbond van Verzekeraars"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "wet-verbetering-poortwachter", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "Burgerlijk Wetboek Boek 7, titel 10 (arbeidsovereenkomst, loondoorbetaling bij ziekte)", "href": "https://wetten.overheid.nl/BWBR0005290", "uitgever": "wetten.overheid.nl"}, {"titel": "UWV: Werkwijzer Poortwachter, WIA en het deskundigenoordeel", "href": "https://www.uwv.nl/", "uitgever": "UWV"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}, {"slug": "zieke-werknemer", "label": "Bronnen", "data": {"heading": "Bronnen", "text": "Waar de termijnen, bedragen en regels in deze gids op gebaseerd zijn.", "items": [{"titel": "Burgerlijk Wetboek Boek 7, titel 10 (arbeidsovereenkomst, loondoorbetaling bij ziekte)", "href": "https://wetten.overheid.nl/BWBR0005290", "uitgever": "wetten.overheid.nl"}, {"titel": "Wet verbetering poortwachter", "href": "https://wetten.overheid.nl/BWBR0013063", "uitgever": "wetten.overheid.nl"}, {"titel": "Autoriteit Persoonsgegevens: wat een werkgever mag vastleggen bij ziekte", "href": "https://www.autoriteitpersoonsgegevens.nl/", "uitgever": "Autoriteit Persoonsgegevens"}, {"titel": "Rijksoverheid: ziekteverzuim en re-integratie", "href": "https://www.rijksoverheid.nl/onderwerpen/ziekteverzuim-van-het-werk", "uitgever": "Rijksoverheid"}]}}]$bronnen$::jsonb) as x(slug text, label text, data jsonb)
  loop
    select id into pid from public.pages where slug = r.slug;
    if pid is null then
      raise notice 'gids % bestaat nog niet, overgeslagen (draai 0061 eerst)', r.slug;
      continue;
    end if;
    if exists (select 1 from public.blocks where page_id = pid and type = 'gidsBronnen') then
      raise notice 'gids % heeft het blok Bronnen al, overgeslagen', r.slug;
      continue;
    end if;
    select min(sort) into plek from public.blocks where page_id = pid and type = 'gidsHelpt';
    if plek is null then
      select coalesce(max(sort), -1) + 1 into plek from public.blocks where page_id = pid;
    else
      update public.blocks set sort = sort + 1 where page_id = pid and sort >= plek;
    end if;
    insert into public.blocks (page_id, type, label, sort, data) values (pid, 'gidsBronnen', r.label, plek, r.data);
    update public.pages set updated_at = now() where id = pid;
    raise notice 'gids %: blok Bronnen op plek %', r.slug, plek;
  end loop;
end $$;

commit;
